  if(cloak.trapGuard&&globalThis.__MANRU_RANDOM57__()<cloak.trapGuard){setTerrainTile58(state.map,x,y,TT.FLOOR);burst(x,y,'#b6a98d',9,.55);floatText(x,y,'완충','#d7c9ac',10);addLog(`${cloak.name}가 함정 충격을 받아냈다.`);return true}
