    const put=(x,y,t)=>{if(x<=r.x||y<=r.y||x>=r.x+r.w-1||y>=r.y+r.h-1)return;if((x===state.player.x&&y===state.player.y)||(x===state.stairs.x&&y===state.stairs.y))return;setTerrainTile58(state.map,x,y,t)};
