    rect1020(x,y,w,h,TT.WALL,true);rect1020(x+1,y+1,w-2,h-2,TT.WOOD_FLOOR,true);door1020(cx,gateY);rect1020(cx-1,y+1,2,h-2,TT.WOOD_FLOOR,true);
    const cuts=[y+5,y+10];for(const yy of cuts)for(let xx=x+1;xx<x+w-1;xx++)setTerrainTile58(state.map,xx,yy,TT.WALL);for(const yy of cuts){door1020(cx-1,yy);door1020(cx,yy)}
