function branchInvalidateTerrain105(map,x,y){
 if(map!==BRANCH_RENDER_MAP)return;
 // Wall lips, bridge rails and shoreline blends depend on nearby cells.
 for(let yy=Math.max(0,y-2);yy<=Math.min(map.length-1,y+2);yy++)for(let xx=Math.max(0,x-2);xx<=Math.min(map[0].length-1,x+2);xx++)BRANCH_TILE_CACHE.delete(yy*map[0].length+xx);
}






