 const anchors=[[14,69,1],[19,48,1],[12,27,1],[30,13,1],[37,37,0],[47,66,0],[65,51,1],[61,30,1],[65,11,1]];
 const nodes=anchors.map(([ax,ay,indoor],id)=>({id,cx:Math.round(ax*1.1)+4+ri(-2,2),cy:Math.round(ay*1.1)+4+ri(-2,2),indoor:!!indoor,style:(id+level)%3,cells:[],ports:[]}));
 const treasury=nodes[rng()<.5?3:5];treasury.special='treasury';nodes[rng()<.5?6:7].special='cart-store';const oilNode=rng()<.5?1:2;nodes[oilNode].special='oil-cache';nodes[oilNode===1?2:1].special='washery';nodes[treasury.id===5?4:5].special='supply-deck';
 // Ordinary excavations are narrow bent fingers. Only purpose-built districts get wider footprints.
 for(const n of nodes){const dest=n.indoor?rock:wood;
  if(n.special){for(let dy=-4;dy<=4;dy++)for(let dx=-5;dx<=5;dx++)if(Math.abs(dx)+Math.abs(dy)<=7)setCell(dest,n.cx+dx,n.cy+dy);}
  else{for(let dy=-3;dy<=3;dy++){const shift=dy<-1?-1:dy>1?1:0;for(let dx=0;dx<2;dx++)setCell(dest,n.cx+shift+dx,n.cy+dy);}for(let dx=-3;dx<=3;dx++)setCell(dest,n.cx+dx,n.cy);}
  setCell(dest,n.cx,n.cy);data.districts.push(n);
 }
 const route=(points)=>{const expanded=[points[0]];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],dx=Math.sign(b.x-a.x),dy=Math.sign(b.y-a.y),length=Math.abs(b.x-a.x)+Math.abs(b.y-a.y);if((a.x===b.x||a.y===b.y)&&length>5){const offset=ri(1,2)*(rng()<.5?-1:1),one=Math.floor(length/3),two=Math.floor(length*2/3),p={x:a.x+dx*one,y:a.y+dy*one},q={x:a.x+dx*two,y:a.y+dy*two};if(inside(p.x+dy*offset,p.y+dx*offset)&&inside(q.x+dy*offset,q.y+dx*offset))expanded.push(p,{x:p.x+dy*offset,y:p.y+dx*offset},{x:q.x+dy*offset,y:q.y+dx*offset},q);}expanded.push(b);}const out=[{...expanded[0]}];for(let i=1;i<expanded.length;i++){const d=expanded[i];let q=out[out.length-1];while(q.x!==d.x||q.y!==d.y){q={x:q.x+Math.sign(d.x-q.x),y:q.y+(q.x===d.x?Math.sign(d.y-q.y):0)};out.push(q);}}return out;};
 const edges=[[0,1,'shaft'],[1,2,'shaft'],[2,3,'shaft'],[6,7,'shaft'],[7,8,'shaft'],[0,5,'bridge'],[5,6,'bridge'],[1,4,'bridge'],[4,7,'bridge'],[2,4,'bridge'],[3,8,'bridge'],[4,6,'bridge'],[4,5,'bridge']];
 for(const [ai,bi,kind]of edges){const a=nodes[ai],b=nodes[bi],mid={x:Math.round((a.cx+b.cx)/2)+ri(-3,3),y:Math.round((a.cy+b.cy)/2)+ri(-3,3)};
  const points=kind==='shaft'?[{x:a.cx,y:a.cy},{x:a.cx,y:mid.y},{x:b.cx,y:mid.y},{x:b.cx,y:b.cy}]:[{x:a.cx,y:a.cy},{x:mid.x,y:a.cy},{x:mid.x,y:mid.y},{x:b.cx+ri(-3,3),y:mid.y},{x:b.cx,y:mid.y},{x:b.cx,y:b.cy}];
  const cells=route(points);for(const q of cells){if(kind==='shaft')setCell(rock,q.x,q.y);else setCell(wood,q.x,q.y);protectedCells.add(key(q.x,q.y));}
  data.edges.push({a:ai,b:bi,kind,route:cells});
 }

