  for(let dy=-4;dy<=4;dy++)for(let dx=-5;dx<=5;dx++)if(Math.abs(dx)+Math.abs(dy)<=7){const q=at(dx,dy);paint(dx,dy,base);area.cells.push(q);data.specialCells[key(q.x,q.y)]=n.special;protectedCells.add(key(q.x,q.y));}
