 if(d.version>=8&&d.unified&&(!d.beds105.length||d.zones.length!==5))errors.push('dense precinct structure incomplete');
 const keyAudit=dojoKeyAudit105();if(!keyAudit.ok)errors.push('dojo key progression');
 let routeCoverage=null;
 if(d.mainRoute105){const from=state.branchPortals105.find(p=>p.id==='up'),goal=d.mainRoute105.at(-1),prev=new Map([[k(from.x,from.y),null]]),q=[from],walk=(x,y)=>pass(state.map[y]?.[x])&&state.map[y]?.[x]!==TT.SCREEN;for(let i=0;i<q.length;i++){const a=q[i];if(a.x===goal.x&&a.y===goal.y)break;for(const [dx,dy]of DIRS8){const x=a.x+dx,y=a.y+dy,key=k(x,y);if(prev.has(key)||!walk(x,y)||dx&&dy&&(!walk(x-dx,y)||!walk(x,y-dy)))continue;prev.set(key,k(a.x,a.y));q.push({x,y});}}const path=[];let key=k(goal.x,goal.y);if(!prev.has(key))errors.push('main route requires screen/hazard');else while(key){const [x,y]=key.split(',').map(Number);path.push({x,y});key=prev.get(key);}const visited=d.spaces.filter(r=>path.some(p=>p.x>=r.x&&p.x<r.x+r.w&&p.y>=r.y&&p.y<r.y+r.h));const mainRooms=d.spaces.filter(r=>r.mainIndex!=null),visitedMain=visited.filter(r=>r.mainIndex!=null);routeCoverage={rooms:visited.length,total:d.spaces.length,ratio:visited.length/d.spaces.length,missedMain:mainRooms.filter(r=>!visitedMain.includes(r)).map(r=>r.mainIndex),mainRooms:visitedMain.length,mainTotal:mainRooms.length,mainRatio:visitedMain.length/mainRooms.length,steps:path.length};const visitedZones=d.zones.filter(z=>visited.some(r=>r.zone===z.id));routeCoverage.zones=visitedZones.length;if(visitedZones.length!==d.zones.length)errors.push('main route skips precinct');}
 const maxTransfer=Math.max(4,...(window.MANRU_TALISMANS||[]).filter(t=>String(t.talismanKind).includes('blink')).map(t=>t.targetRange||5));for(let i=0;i<d.sectors.length-1;i++)if(d.sectors[i+1].x-(d.sectors[i].x+d.sectors[i].w)<=maxTransfer)errors.push('transfer gap');
