function citadelRelicInfluence105(tower,level){
 let nearest=null;for(const site of CITADEL_RELIC_SITES105){const queue=[{tower:site.tower,level:site.level,distance:0}],seen=new Set();let distance=Infinity;
  for(let n=0;n<queue.length;n++){const q=queue[n],key=q.tower+':'+q.level;if(seen.has(key))continue;seen.add(key);if(q.tower===tower&&q.level===level){distance=q.distance;break;}if(q.distance>=6)continue;
   if(q.level>1)queue.push({...q,level:q.level-1,distance:q.distance+1});if(q.level<CITADEL_TOWERS105[q.tower].height)queue.push({...q,level:q.level+1,distance:q.distance+1});
   for(const[a,b,l]of CITADEL_LINKS105)if(l===q.level&&(a===q.tower||b===q.tower))queue.push({tower:a===q.tower?b:a,level:l,distance:q.distance+1});
  }if(distance<=6&&(!nearest||distance<nearest.distance))nearest={site,distance,stage:distance===0?4:distance<=2?3:distance<=4?2:1};
 }return nearest;
}
function citadelRelicStrength105(distance){return Math.max(0,Math.min(1,.14+(6-distance)*.13));}


function citadelWorld105(){return citadelEnsurePlan105();}
function citadelRawInside105(t,x,y){
 const u=x-t.x,v=y-t.y;
 if(!t.pieces105){const a=Math.abs(u),b=Math.abs(v),r=t.r;return (t.shape==='round'?a*a+b*b<=r*r:t.shape==='octagon'?Math.max(a,b)<=r&&a+b<=r*1.65:Math.max(a,b)<=r&&!(a>r-4&&b>r-4))||(a<=5&&b<=r+3)||(b<=5&&a<=r+3)||(a<=Math.min(r,16)&&b<=Math.min(r,16));}
 for(const p of t.pieces105){if(p[0]==='poly'){let hit=false;const a=p[1];for(let i=0,j=a.length-1;i<a.length;j=i++){const A=a[j],B=a[i],cross=(u-A[0])*(B[1]-A[1])-(v-A[1])*(B[0]-A[0]);if(Math.abs(cross)<1e-8&&u>=Math.min(A[0],B[0])&&u<=Math.max(A[0],B[0])&&v>=Math.min(A[1],B[1])&&v<=Math.max(A[1],B[1]))return true;if((A[1]>v)!==(B[1]>v)&&u<(B[0]-A[0])*(v-A[1])/(B[1]-A[1])+A[0])hit=!hit;}if(hit)return true;}else{const a=Math.abs(u-p[1]),b=Math.abs(v-p[2]);if(p[0]==='rect'?a<=p[3]&&b<=p[4]:p[0]==='circle'?a*a+b*b<=p[3]*p[3]:a<=p[3]&&b<=p[4]&&a/p[3]+b/p[4]<=1.7)return true;}}
 return (t.rooms105||[]).some(([cx,cy,w,h])=>Math.abs(u-cx)<=(w-1)/2+1&&Math.abs(v-cy)<=(h-1)/2+1);
}
function citadelInside105(t,x,y,inset=0){if(!t)return false;if(!citadelRawInside105(t,x,y))return false;if(inset<=0)return true;for(let dy=-inset;dy<=inset;dy++)for(let dx=-inset;dx<=inset;dx++)if(!citadelRawInside105(t,x+dx,y+dy))return false;return true;}
function citadelCoreTower105(){const data=state.branchTerrain105?.citadel105,id=data?.centralId105??(data&&data.version<4?8:12);return data?.towers?.find(t=>t.id===id)||CITADEL_TOWERS105[12];}
function citadelCombatDepth105(x,y,level=state.branchContext105?.level||1){const data=state.branchTerrain105?.citadel105,t=(data?.towers||CITADEL_TOWERS105).find(t=>citadelInside105(t,x,y))||CITADEL_TOWERS105[20];const depth=t.id===citadelCoreTower105().id?25+4-level:t.concept105==='prison'?23:['tomb','ossuary'].includes(t.concept105)?24:['fortress','command','treasury'].includes(t.concept105)?25:20+Math.min(4,Math.floor(t.id/5));return depth+CITADEL_COMBAT_OFFSET105;}
function citadelAccess105(x,y){return state?.branchContext105?.id!=='citadel'||state.branchContext105.level===4||!citadelInside105(citadelCoreTower105(),x,y)||!!state.branchWorld105?.citadel105?.enteredCentral;}

function citadelEntranceRoom105(required=true){
 const reach=ReachabilityService.playerSearch(state.player,{unlock:true,openBoss:true}).cells,candidates=[];
 // Produce the entrance chamber in a vacant 5x5 site, including its enclosing walls.
 for(const room of state.rooms||[]){if(room.w<7||room.h<7||room.branchEntrance105)continue;
  for(let y=room.y+3;y<room.y+room.h-3;y++)for(let x=room.x+3;x<room.x+room.w-3;x++){
   if(entityDistance57({x,y},state.stairs)<6||entityDistance57({x,y},state.player)<4)continue;let safe=true;
   for(let dy=-2;dy<=2&&safe;dy++)for(let dx=-2;dx<=2;dx++){const xx=x+dx,yy=y+dy,t=state.map[yy]?.[xx];if(!reach.has(k(xx,yy))||!terrainSurface58(t)||[TT.WATER,TT.LAVA,TT.MERCURY,TT.VOID,TT.PORTAL,TT.STAIR,TT.KEY_TILE,TT.LOCKED_GATE].includes(t)||OccupancyService.isOccupied(xx,yy)||state.items.some(i=>i.x===xx&&i.y===yy)){safe=false;break;}}
   if(safe)candidates.push({x,y,room,score:room.w*room.h-entityDistance57({x,y},state.player)});
  }
 }
 candidates.sort((a,b)=>b.score-a.score||a.y-b.y||a.x-b.x);const p=candidates[0];if(!p){if(required)throw Error('흑성채 전용 출입실 부지 없음');return null;}
 for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const border=Math.max(Math.abs(dx),Math.abs(dy))===2,door=border&&(dx===0||dy===0);setTerrainTile58(state.map,p.x+dx,p.y+dy,border?(door?TT.OPEN_DOOR:TT.WALL):TT.STONE_PATH);}
 const chamber={x:p.x-2,y:p.y-2,w:5,h:5,name:'흑성채 출입실',branchEntrance105:'citadel'};state.rooms.push(chamber);state.featureRooms.push({...chamber});
 for(const [dx,dy]of [[-1,-1],[1,-1],[-1,1],[1,1]])state.decor.push({x:p.x+dx,y:p.y+dy,kind:'banner',label:'흑성채 문장'});
 return{x:p.x,y:p.y};
}

