function anvilNearby105(q){const p=state?.player;return !!p&&entityDistance57(q,p)<=1&&(q.x===p.x||q.y===p.y||!runtimeTerrainSolid57(state.map[p.y]?.[q.x])&&!runtimeTerrainSolid57(state.map[q.y]?.[p.x]));}
